Error Return Traces show all the points in the code that an error was returned to the calling function. This makes it practical to use try everywhere and then still be able to know what happened if an error ends up bubbling all the way out of your application.
 error_return_trace.zig pub fn main () ! void {
 try foo( 12 );
}
 fn foo (x: i32 ) ! void {
 if (x >= 5 ) {
 try bar();
 } else {
 try bang2();
 }
}
 fn bar () ! void {
 if (baz()) {
 try quux();
 } else |err| switch (err) {
 error .FileNotFound => try hello(),
 }
}
 fn baz () ! void {
 try bang1();
}
 fn quux () ! void {
 try bang2();
}
 fn hello () ! void {
 try bang2();
}
 fn bang1 () ! void {
 return error .FileNotFound;
}
 fn bang2 () ! void {
 return error .PermissionDenied;
} Shell $ zig build-exe error_return_trace.zig 
$ ./error_return_trace 
error: PermissionDenied
/home/ci/work/zig-bootstrap/zig/doc/langref/error_return_trace.zig:34:5: 0x11d6a8c in bang1 (error_return_trace.zig)
 return error.FileNotFound;
 ^
