 try bang1();
 ^
/home/ci/work/zig-bootstrap/zig/doc/langref/error_return_trace.zig:38:5: 0x11d6b2c in bang2 (error_return_trace.zig)
 return error.PermissionDenied;
 ^
/home/ci/work/zig-bootstrap/zig/doc/langref/error_return_trace.zig:30:5: 0x11d6c07 in hello (error_return_trace.zig)
 try bang2();
 ^
/home/ci/work/zig-bootstrap/zig/doc/langref/error_return_trace.zig:17:31: 0x11d6d15 in bar (error_return_trace.zig)
 error.FileNotFound => try hello(),
 ^
/home/ci/work/zig-bootstrap/zig/doc/langref/error_return_trace.zig:7:9: 0x11d6df5 in foo (error_return_trace.zig)
