const std = @import("std");
const bsvz = @import("bsvz");

pub const nonempty_invalid_der_signature = [_]u8{
    0x30, 0x06, 0x02, 0x01, 0x01, 0x02, 0x01, 0x01, 0x01,
};

pub fn encodeLowerAlloc(allocator: std.mem.Allocator, bytes: []const u8) ![]u8 {
    const out = try allocator.alloc(u8, bytes.len * 2);
    return try bsvz.primitives.hex.encodeLower(bytes, out);
}

pub fn scriptHexFromBytes(allocator: std.mem.Allocator, bytes: []const u8) ![]u8 {
    return encodeLowerAlloc(allocator, bytes);
}

pub fn appendPushData(
    bytes: *std.ArrayListUnmanaged(u8),
    allocator: std.mem.Allocator,
    data: []const u8,
) !void {
    if (data.len <= 75) {
        try bytes.append(allocator, @intCast(data.len));
    } else unreachable;
    try bytes.appendSlice(allocator, data);
}

pub fn scriptHexForOps(allocator: std.mem.Allocator, ops: []const bsvz.script.opcode.Opcode) ![]u8 {
    var bytes: std.ArrayListUnmanaged(u8) = .empty;
    defer bytes.deinit(allocator);
    for (ops) |op| try bytes.append(allocator, @intFromEnum(op));
    return scriptHexFromBytes(allocator, bytes.items);
}

pub fn scriptNumBytes(allocator: std.mem.Allocator, value: i64) ![]u8 {
    return bsvz.script.ScriptNum.encode(allocator, value);
}

pub fn repeatedHexByte(allocator: std.mem.Allocator, count: usize, byte: u8) ![]u8 {
    const bytes = try allocator.alloc(u8, count);
    @memset(bytes, byte);
    return bytes;
}

pub fn buildSyntheticCheckmultisigNotHexes(
    allocator: std.mem.Allocator,
    dummy_opcode: u8,
    nonempty_sig_index: ?usize,
) !struct { unlocking_hex: []u8, locking_hex: []u8 } {
    var unlocking_bytes: std.ArrayListUnmanaged(u8) = .empty;
    defer unlocking_bytes.deinit(allocator);
    var locking_bytes: std.ArrayListUnmanaged(u8) = .empty;
    defer locking_bytes.deinit(allocator);

    try unlocking_bytes.append(allocator, dummy_opcode);
    for (0..20) |index| {
        if (nonempty_sig_index != null and nonempty_sig_index.? == index) {
            try unlocking_bytes.append(allocator, nonempty_invalid_der_signature.len);
            try unlocking_bytes.appendSlice(allocator, &nonempty_invalid_der_signature);
        } else {
            try unlocking_bytes.append(allocator, 0x00);
        }
    }

    try locking_bytes.appendSlice(allocator, &[_]u8{ 0x01, 0x14 });
    for (0..20) |_| try locking_bytes.append(allocator, 0x51);
    try locking_bytes.appendSlice(allocator, &[_]u8{
        0x01,
        0x14,
        @intFromEnum(bsvz.script.opcode.Opcode.OP_CHECKMULTISIG),
        @intFromEnum(bsvz.script.opcode.Opcode.OP_NOT),
    });

    return .{
        .unlocking_hex = try encodeLowerAlloc(allocator, unlocking_bytes.items),
        .locking_hex = try encodeLowerAlloc(allocator, locking_bytes.items),
    };
}

//! A wrapper over a byte-slice, providing useful methods for parsing string floating point values.

const std = @import("std");
const FloatStream = @This();
const common = @import("common.zig");

slice: []const u8,
offset: usize,
underscore_count: usize,

pub fn init(s: []const u8) FloatStream {
    return .{ .slice = s, .offset = 0, .underscore_count = 0 };
}

// Returns the offset from the start *excluding* any underscores that were found.
pub fn offsetTrue(self: FloatStream) usize {
    return self.offset - self.underscore_count;
}

pub fn reset(self: *FloatStream) void {
    self.offset = 0;
    self.underscore_count = 0;
}

pub fn len(self: FloatStream) usize {
    if (self.offset > self.slice.len) {
        return 0;
    }
    return self.slice.len - self.offset;
}

pub fn hasLen(self: FloatStream, n: usize) bool {
    return self.offset + n <= self.slice.len;
}

pub fn firstUnchecked(self: FloatStream) u8 {
    return self.slice[self.offset];
}

pub fn first(self: FloatStream) ?u8 {
    return if (self.hasLen(1))
        return self.firstUnchecked()
    else
        null;
}

pub fn isEmpty(self: FloatStream) bool {
    return !self.hasLen(1);
}

pub fn firstIs(self: FloatStream, comptime cs: []const u8) bool {
    if (self.first()) |ok| {
        inline for (cs) |c| if (ok == c) return true;
    }
    return false;
}

pub fn firstIsLower(self: FloatStream, comptime cs: []const u8) bool {
    if (self.first()) |ok| {
        inline for (cs) |c| if (ok | 0x20 == c) return true;
    }
    return false;
}

pub fn firstIsDigit(self: FloatStream, comptime base: u8) bool {
    comptime std.debug.assert(base == 10 or base == 16);

    if (self.first()) |ok| {
        return common.isDigit(ok, base);
    }
    return false;
}

pub fn advance(self: *FloatStream, n: usize) void {
    self.offset += n;
}

pub fn skipChars(self: *FloatStream, comptime cs: []const u8) void {
    while (self.firstIs(cs)) : (self.advance(1)) {}
}

pub fn readU64Unchecked(self: FloatStream) u64 {
    return std.mem.readInt(u64, self.slice[self.offset..][0..8], .little);
}

pub fn readU64(self: FloatStream) ?u64 {
    if (self.hasLen(8)) {
        return self.readU64Unchecked();
    }
    return null;
}

pub fn atUnchecked(self: *FloatStream, i: usize) u8 {
    return self.slice[self.offset + i];
}

pub fn scanDigit(self: *FloatStream, comptime base: u8) ?u8 {
    comptime std.debug.assert(base == 10 or base == 16);

    retry: while (true) {
        if (self.first()) |ok| {
            if ('0' <= ok and ok <= '9') {
                self.advance(1);
                return ok - '0';
            } else if (base == 16 and 'a' <= ok and ok <= 'f') {
                self.advance(1);
                return ok - 'a' + 10;
            } else if (base == 16 and 'A' <= ok and ok <= 'F') {
                self.advance(1);
                return ok - 'A' + 10;
            } else if (ok == '_') {
                self.advance(1);
                self.underscore_count += 1;
                continue :retry;
            }
        }
        return null;
    }
}

const std = @import("std");
const bsvz = @import("bsvz");

const Script = bsvz.script.Script;

pub const Expectation = union(enum) {
    success: bool,
    err: anyerror,
};

pub const Case = struct {
    name: []const u8,
    unlocking_hex: []const u8,
    locking_hex: []const u8,
    flags: bsvz.script.engine.ExecutionFlags,
    expected: Expectation,
    previous_satoshis: i64 = 1_000,
    tx_version: i32 = 2,
    tx_lock_time: u32 = 0,
    input_sequence: u32 = 0xffff_fffe,
};

pub fn runCase(allocator: std.mem.Allocator, case: Case) !void {
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const unlocking_bytes = try decodeScriptHex(arena, case.unlocking_hex);
    const locking_bytes = try decodeScriptHex(arena, case.locking_hex);

    const unlocking_script = Script.init(unlocking_bytes);
    const locking_script = Script.init(locking_bytes);

    var inputs = [_]bsvz.transaction.Input{
        .{
            .previous_outpoint = .{
                .txid = .{ .bytes = @as([32]u8, @splat(0x42)) },
                .index = 0,
            },
            .unlocking_script = Script.init(""),
            .sequence = case.input_sequence,
        },
    };
    var outputs = [_]bsvz.transaction.Output{
        .{
            .satoshis = case.previous_satoshis - 1,
            .locking_script = locking_script,
        },
    };
    const tx = bsvz.transaction.Transaction{
        .version = case.tx_version,
        .inputs = &inputs,
        .outputs = &outputs,
        .lock_time = case.tx_lock_time,
    };

    var exec_ctx = bsvz.script.engine.ExecutionContext.forSpend(
        allocator,
        &tx,
        0,
        case.previous_satoshis,
    );
    exec_ctx.previous_locking_script = locking_script;
    exec_ctx.flags = case.flags;

    const result = bsvz.script.thread.verifyScripts(exec_ctx, unlocking_script, locking_script);

    switch (case.expected) {
        .success => |want| try std.testing.expectEqual(want, try result),
        .err => |want_err| try std.testing.expectError(want_err, result),
    }
}

fn decodeScriptHex(allocator: std.mem.Allocator, text: []const u8) ![]u8 {
    var normalized: std.ArrayListUnmanaged(u8) = .empty;
    defer normalized.deinit(allocator);

    var index: usize = 0;
    while (index < text.len) {
        const ch = text[index];
        if (std.ascii.isWhitespace(ch) or ch == ',') {
            index += 1;
            continue;
        }
        if (ch == '0' and index + 1 < text.len and (text[index + 1] == 'x' or text[index + 1] == 'X')) {
            index += 2;
            continue;
        }

        try normalized.append(allocator, ch);
        index += 1;
    }

    return bsvz.primitives.hex.decode(allocator, normalized.items);
}

